-- Add confirmed flavor descriptions without changing availability or voting eligibility.
-- Existing nonempty descriptions and all other content fields are preserved.
UPDATE contenido SET valor = json_set(valor, '$[' || (SELECT key FROM json_each(contenido.valor) WHERE json_extract(value, '$.nombre') = 'Enrique' LIMIT 1) || '].que', 'Maní para rato'), actualizado = unixepoch() * 1000, por = 'plan-2026-11-10' WHERE clave = 'carta' AND json_valid(valor) AND EXISTS (SELECT 1 FROM json_each(contenido.valor) WHERE json_extract(value, '$.nombre') = 'Enrique' AND COALESCE(json_extract(value, '$.que'), '') = '');
